+
+            if (previous != null) {
+                throw new IllegalStateException("Result partition already registered.");
+            }
+
+            listenerManager = listenerManagers.remove(partition.getPartitionId());
+        }
+        if (listenerManager != null) {
+            for (PartitionRequestListener listener :
