1169:     /**
1170:      * Sets all relevant options contained in the {@link ReadableConfig} such as e.g. {@link
1171:      * PipelineOptions#CLOSURE_CLEANER_LEVEL}.
1172:      *
1173:      * <p>It will change the value of a setting only if a corresponding option was set in the {@code
1174:      * configuration}. If a key is not present, the current value of a field will remain untouched.
1175:      *
1176:      * @param configuration a configuration to read the values from
1177:      * @param classLoader a class loader to use when loading classes
1178:      */
1179:     public void configure(ReadableConfig configuration, ClassLoader classLoader) {
1180:         configuration
1181:                 .getOptional(PipelineOptions.AUTO_TYPE_REGISTRATION)
1182:                 .ifPresent(this::setAutoTypeRegistration);
1183:         configuration
1184:                 .getOptional(PipelineOptions.AUTO_GENERATE_UIDS)
1185:                 .ifPresent(this::setAutoGeneratedUids);
1186:         configuration
1187:                 .getOptional(PipelineOptions.AUTO_WATERMARK_INTERVAL)
1188:                 .ifPresent(this::setAutoWatermarkInterval);
1189:         configuration
1190:                 .getOptional(PipelineOptions.CLOSURE_CLEANER_LEVEL)
1191:                 .ifPresent(this::setClosureCleanerLevel);
1192:         configuration.getOptional(PipelineOptions.FORCE_AVRO).ifPresent(this::setForceAvro);
1193:         configuration.getOptional(PipelineOptions.GENERIC_TYPES).ifPresent(this::setGenericTypes);
1194:         configuration.getOptional(PipelineOptions.FORCE_KRYO).ifPresent(this::setForceKryo);
1195:         configuration
1196:                 .getOptional(PipelineOptions.GLOBAL_JOB_PARAMETERS)
1197:                 .ifPresent(this::setGlobalJobParameters);
1198: 
1199:         configuration
1200:                 .getOptional(MetricOptions.LATENCY_INTERVAL)
1201:                 .ifPresent(this::setLatencyTrackingInterval);
1202: 
1203:         configuration
1204:                 .getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_ENABLED)
1205:                 .ifPresent(this::enablePeriodicMaterialize);
1206:         configuration
1207:                 .getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_INTERVAL)
1208:                 .ifPresent(this::setPeriodicMaterializeIntervalMillis);
1209:         configuration
1210:                 .getOptional(StateChangelogOptions.MATERIALIZATION_MAX_FAILURES_ALLOWED)
1211:                 .ifPresent(this::setMaterializationMaxAllowedFailures);
1212: 
1213:         configuration
1214:                 .getOptional(PipelineOptions.MAX_PARALLELISM)
1215:                 .ifPresent(this::setMaxParallelism);
1216:         configuration.getOptional(CoreOptions.DEFAULT_PARALLELISM).ifPresent(this::setParallelism);
1217:         configuration.getOptional(PipelineOptions.OBJECT_REUSE).ifPresent(this::setObjectReuse);
1218:         configuration
1219:                 .getOptional(TaskManagerOptions.TASK_CANCELLATION_INTERVAL)
1220:                 .ifPresent(this::setTaskCancellationInterval);
1221:         configuration
1222:                 .getOptional(TaskManagerOptions.TASK_CANCELLATION_TIMEOUT)
1223:                 .ifPresent(this::setTaskCancellationTimeout);
1224:         configuration
1225:                 .getOptional(ExecutionOptions.SNAPSHOT_COMPRESSION)
1226:                 .ifPresent(this::setUseSnapshotCompression);
1227:         configuration
1228:                 .getOptional(RestartStrategyOptions.RESTART_STRATEGY)
1229:                 .ifPresent(
1230:                         s -> {
1231:                             this.setRestartStrategy(configuration);
1232:                             // reset RestartStrategies for backward compatibility
1233:                             this.setRestartStrategy(
1234:                                     new RestartStrategies.FallbackRestartStrategyConfiguration());
1235:                         });
1236:         configuration
1237:                 .getOptional(PipelineOptions.KRYO_DEFAULT_SERIALIZERS)
1238:                 .map(s -> parseKryoSerializersWithExceptionHandling(classLoader, s))
1239:                 .ifPresent(s -> this.defaultKryoSerializerClasses = s);
1240: 
1241:         configuration
1242:                 .getOptional(PipelineOptions.POJO_REGISTERED_CLASSES)
1243:                 .map(c -> loadClasses(c, classLoader, "Could not load pojo type to be registered."))
1244:                 .ifPresent(c -> this.registeredPojoTypes = c);
1245: 
1246:         configuration
1247:                 .getOptional(PipelineOptions.KRYO_REGISTERED_CLASSES)
1248:                 .map(c -> loadClasses(c, classLoader, "Could not load kryo type to be registered."))
1249:                 .ifPresent(c -> this.registeredKryoTypes = c);
1250: 
1251:         configuration
1252:                 .getOptional(JobManagerOptions.SCHEDULER)
1253:                 .ifPresent(t -> this.configuration.set(JobManagerOptions.SCHEDULER, t));
1254:     }
