1256:     private void setRestartStrategy(ReadableConfig configuration) {
1257:         Map<String, String> map = configuration.toMap();
1258:         Map<String, String> restartStrategyEntries = new HashMap<>();
1259:         for (Map.Entry<String, String> entry : map.entrySet()) {
1260:             if (entry.getKey().startsWith(RestartStrategyOptions.RESTART_STRATEGY_CONFIG_PREFIX)) {
1261:                 restartStrategyEntries.put(entry.getKey(), entry.getValue());
1262:             }
1263:         }
1264:         this.configuration.addAll(Configuration.fromMap(restartStrategyEntries));
1265:     }
