1277:     private LinkedHashSet<Class<?>> loadClasses(
1278:             List<String> classNames, ClassLoader classLoader, String errorMessage) {
1279:         return classNames.stream()
1280:                 .map(name -> this.<Class<?>>loadClass(name, classLoader, errorMessage))
1281:                 .collect(Collectors.toCollection(LinkedHashSet::new));
