1284:     private LinkedHashMap<Class<?>, Class<? extends Serializer<?>>>
1285:             parseKryoSerializersWithExceptionHandling(
1286:                     ClassLoader classLoader, List<String> kryoSerializers) {
1287:         try {
1288:             return parseKryoSerializers(classLoader, kryoSerializers);
1289:         } catch (Exception e) {
1290:             throw new IllegalArgumentException(
1291:                     String.format(
1292:                             "Could not configure kryo serializers from %s. The expected format is:"
1293:                                     + "'class:<fully qualified class name>,serializer:<fully qualified serializer name>;...",
1294:                             kryoSerializers),
1295:                     e);
1296:         }
1297:     }
1298: 
1299:     private LinkedHashMap<Class<?>, Class<? extends Serializer<?>>> parseKryoSerializers(
1300:             ClassLoader classLoader, List<String> kryoSerializers) {
1301:         return kryoSerializers.stream()
1302:                 .map(ConfigurationUtils::parseStringToMap)
1303:                 .collect(
1304:                         Collectors.toMap(
1305:                                 m ->
1306:                                         loadClass(
1307:                                                 m.get("class"),
1308:                                                 classLoader,
1309:                                                 "Could not load class for kryo serialization"),
1310:                                 m ->
1311:                                         loadClass(
1312:                                                 m.get("serializer"),
1313:                                                 classLoader,
1314:                                                 "Could not load serializer's class"),
1315:                                 (m1, m2) -> {
1316:                                     throw new IllegalArgumentException(
1317:                                             "Duplicated serializer for class: " + m1);
1318:                                 },
1319:                                 LinkedHashMap::new));
1320:     }
