+		while (iterator.hasNext()) {
+			Entry<Long, DataType> entry = iterator.next();
+			Long key = entry.getKey();
+			DataType valDT = entry.getValue();
+			if (key.intValue() < 0) {
+				// println("    BAD OFFSET : " + key.intValue());
+				continue;
+			}
