57: 		Varnode varnode;		// The traced Varnode
58: 		long offset;			// Offset relative to original pointer
59: 
60: 		public PointerRef(Varnode ref, long off) {
61: 			varnode = ref;
62: 			offset = off;
63: 		}
64: 	}
