91: 	public FillOutStructureCmd(Program program, ProgramLocation location, PluginTool tool) {
92: 		super("Fill Out Structure", true, false, true);
93: 		this.tool = tool;
94: 		this.currentProgram = program;
95: 		this.currentLocation = Objects.requireNonNull(location);
