98: 	@Override
99: 	public boolean applyTo(DomainObject obj, TaskMonitor taskMonitor) {
100: 		this.monitor = taskMonitor;
101: 
102: 		rootFunction =
103: 			currentProgram.getFunctionManager().getFunctionContaining(currentLocation.getAddress());
104: 		if (rootFunction == null) {
105: 			return false;
106: 		}
107: 
108: 		int transaction = currentProgram.startTransaction("Fill Out Structure Variable");
109: 		try {
110: 			HighVariable var = null;
111: 
112: 			if (!(currentLocation instanceof DecompilerLocation)) {
113: 				// if we don't have one, make one, and map variable to a varnode
114: 				Address storageAddr = computeStorageAddress(currentLocation, rootFunction);
115: 				var = computeHighVariable(storageAddr, rootFunction);
116: 			}
117: 			else {
118: 
119: 				// get the Varnode under the cursor
120: 				DecompilerLocation dloc = (DecompilerLocation) currentLocation;
121: 				ClangToken token = dloc.getToken();
122: 				if (token == null) {
123: 					return false;
124: 				}
125: 
126: 				var = token.getHighVariable();
127: 				Varnode exactSpot = token.getVarnode();
128: 
129: 				if ((var != null) && (exactSpot != null)) {
130: 					HighFunction hfunc = var.getHighFunction();
131: 					try { // Adjust HighVariable based on exact varnode selected, if there are merged groups
132: 						var = hfunc.splitOutMergeGroup(var, exactSpot);
133: 					}
134: 					catch (PcodeException ex) {
135: 						return false;
136: 					}
137: 				}
138: 			}
139: 
140: 			if (var == null || var.getSymbol() == null || var.getOffset() >= 0) {
141: 				return false;
142: 			}
143: 
144: 			boolean isThisParam =
145: 				CreateStructureVariableAction.testForAutoParameterThis(var, rootFunction);
146: 			Structure structDT =
147: 				CreateStructureVariableAction.getStructureForExtending(var.getDataType());
148: 			if (structDT != null) {
149: 				componentMap.populateOriginalStructure(structDT);
150: 			}
151: 
152: 			fillOutStructureDef(var);
153: 			pushIntoCalls();
154: 
155: 			structDT = createStructure(structDT, var, rootFunction, isThisParam);
156: 			populateStructure(structDT);
157: 
158: 			DataType pointerDT = new PointerDataType(structDT);
159: 
160: 			// Delay adding to the manager until full structure is accumulated
161: 			pointerDT = currentProgram.getDataTypeManager()
162: 					.addDataType(pointerDT, DataTypeConflictHandler.DEFAULT_HANDLER);
163: 			commitVariable(var, pointerDT, isThisParam);
164: 		}
165: 		catch (Exception e) {
166: 			Msg.showError(this, tool.getToolFrame(), "Auto Create Structure Failed",
167: 				"Failed to create Structure variable", e);
168: 		}
169: 		finally {
170: 			currentProgram.endTransaction(transaction, true);
171: 		}
172: 
173: 		return true;
174: 	}
