176: 	/**
177: 	 * Method to create a structure data type for a variable in the given function.
178: 	 * Unlike the applyTo() action, this method will not modify the function, its variables,
179: 	 * or any existing data-types. A new structure is always created.
180: 	 * @param var a parameter, local variable, or global variable used in the given function
181: 	 * @param function the function to process
182: 	 * @return a filled-in structure or null if one could not be created
183: 	 */
184: 	public Structure processStructure(HighVariable var, Function function) {
185: 
186: 		if (var == null || var.getSymbol() == null || var.getOffset() >= 0) {
187: 			return null;
188: 		}
189: 
190: 		Structure structDT;
191: 
192: 		try {
193: 			fillOutStructureDef(var);
194: 			pushIntoCalls();
195: 			structDT = createStructure(null, var, function, false);
196: 			populateStructure(structDT);
197: 		}
198: 		catch (Exception e) {
199: 			return null;
200: 		}
201: 
202: 		return structDT;
203: 	}
