231: 	/**
232: 	 * Retrieve the (likely) storage address of a function parameter given
233: 	 * the inputs to a CALL p-code op and particular Varnode slot within the inputs.
234: 	 * We compute the address from the point of view of the called function (callee)
235: 	 * which may be different from the point of view of the caller, which may be
236: 	 * different from the address of the Varnode currently holding the parameter.
237: 	 * @param inputs is the array of Varnode inputs to the CALL
238: 	 * @param slot is the index of the Varnode holding the parameter we want.
239: 	 * @return the starting address of the parameter or null if the address can't be identified
240: 	 */
241: 	private Address computeParamAddress(Varnode[] inputs, int slot) {
242: 		Address funcAddr = inputs[0].getAddress();
243: 		Function function = currentProgram.getFunctionManager().getFunctionAt(funcAddr);
244: 		if (function == null) {
245: 			return null;
246: 		}
247: 		Parameter[] parameters = function.getParameters();
248: 		if (slot - 1 < parameters.length) {
249: 			return parameters[slot - 1].getMinAddress();
250: 		}
251: 		PrototypeModel model = function.getCallingConvention();
252: 		if (model == null) {
253: 			model = currentProgram.getCompilerSpec().getDefaultCallingConvention();
254: 			if (model == null) {
255: 				return null;
256: 			}
257: 		}
258: 		DataType typeList[] = new DataType[slot + 1];
259: 		typeList[0] = DataType.DEFAULT;		// Default function return data-type
260: 		for (int i = 1; i < slot + 1; ++i) {
261: 			typeList[i] = inputs[i].getHigh().getDataType();
262: 		}
263: 		VariableStorage[] storageLocations =
264: 			model.getStorageLocations(currentProgram, typeList, false);
265: 		return storageLocations[slot].getMinAddress();
266: 	}
