268: 	/**
269: 	 * Recursively visit calls that take the structure pointer as a parameter.
270: 	 * Add any new references to the offsetToDataTypeMap.
271: 	 */
272: 	private void pushIntoCalls() {
273: 		AddressSet doneSet = new AddressSet();
274: 
275: 		while (addressToCallInputMap.size() > 0) {
276: 			currentCallDepth += 1;
277: 			if (currentCallDepth > maxCallDepth) {
278: 				return;
279: 			}
280: 			HashMap<Address, Address> savedList = addressToCallInputMap;
281: 			addressToCallInputMap = new HashMap<>();
282: 			Set<Address> keys = savedList.keySet();
283: 			for (Address addr : keys) {
284: 				if (doneSet.contains(addr)) {
285: 					continue;
286: 				}
287: 				doneSet.addRange(addr, addr);
288: 				Function func = currentProgram.getFunctionManager().getFunctionAt(addr);
289: 				Address storageAddr = savedList.get(addr);
290: 				HighVariable paramHighVar = computeHighVariable(storageAddr, func);
291: 				if (paramHighVar != null) {
292: 					fillOutStructureDef(paramHighVar);
293: 				}
294: 			}
295: 		}
296: 	}
