320: 	/**
321: 	 * Compute the storage address associated with a particular Location
322: 	 * @param location is the location being queried
323: 	 * @param function is the function owning the location
324: 	 * @return the corresponding storage address or null
325: 	 */
326: 	private Address computeStorageAddress(ProgramLocation location, Function function) {
327: 
328: 		Address storageAddress = null;
329: 
330: 		// make sure what we are over can be mapped to decompiler
331: 		// param, local, etc...
332: 
333: 		if (location instanceof VariableLocation) {
334: 			VariableLocation varLoc = (VariableLocation) location;
335: 			storageAddress = varLoc.getVariable().getVariableStorage().getMinAddress();
336: 		}
337: 		else if (location instanceof FunctionParameterFieldLocation) {
338: 			FunctionParameterFieldLocation funcPFL = (FunctionParameterFieldLocation) location;
339: 			storageAddress = funcPFL.getParameter().getVariableStorage().getMinAddress();
340: 		}
341: 		return storageAddress;
342: 	}
