344: 	/**
345: 	 * Decompile a function and return the resulting HighVariable associated with a storage address
346: 	 * @param storageAddress the storage address of the variable
347: 	 * @param function is the function
348: 	 * @return the corresponding HighVariable
349: 	 */
350: 	private HighVariable computeHighVariable(Address storageAddress, Function function) {
351: 		if (storageAddress == null) {
352: 			return null;
353: 		}
354: 		DecompInterface decomplib = setUpDecompiler();
355: 		HighVariable highVar = null;
356: 
357: 		// call decompiler to get syntax tree
358: 		try {
359: 			if (!decomplib.openProgram(currentProgram)) {
360: 				return null;
361: 			}
362: 
363: 			DecompileResults results = decompileFunction(function, decomplib);
364: 			HighFunction highFunc = results.getHighFunction();
365: 
366: 			// no decompile...
367: 			if (highFunc == null) {
368: 				return null;
369: 			}
370: 
371: 			// try to map the variable
372: 			HighSymbol sym =
373: 				highFunc.getMappedSymbol(storageAddress, function.getEntryPoint().subtractWrap(1L));
374: 			if (sym == null) {
375: 				sym = highFunc.getMappedSymbol(storageAddress, null);
376: 			}
377: 			if (sym == null) {
378: 				sym = highFunc.getMappedSymbol(storageAddress, function.getEntryPoint());
379: 			}
380: 			if (sym == null) {
381: 				sym = highFunc.getLocalSymbolMap()
382: 						.findLocal(storageAddress, function.getEntryPoint().subtractWrap(1L));
383: 			}
384: 			if (sym == null) {
385: 				sym = highFunc.getLocalSymbolMap().findLocal(storageAddress, null);
386: 			}
387: 			if (sym == null) {
388: 				sym = highFunc.getLocalSymbolMap()
389: 						.findLocal(storageAddress, function.getEntryPoint());
390: 			}
391: 			if (sym == null) {
392: 				return null;
393: 			}
394: 
395: 			highVar = sym.getHighVariable();
396: 		}
397: 		finally {
398: 			decomplib.dispose();
399: 		}
400: 
401: 		return highVar;
402: 	}
