436: 	/**
437: 	 * Recover the structure associated with the given pointer variable, or if there is no structure,
438: 	 * create it.  Resize the structure to be at least as large as the maxOffset seen so far.
439: 	 * @param structDT is the structure data-type to fill in, or null if a new Structure should be created
440: 	 * @param var is the given pointer variable
441: 	 * @param f is the function
442: 	 * @param isThisParam is true if the variable is a 'this' pointer
443: 	 * @return the Structure object
444: 	 */
445: 	private Structure createStructure(Structure structDT, HighVariable var, Function f,
446: 			boolean isThisParam) {
447: 
448: 		if (structDT == null) {
449: 			structDT = createNewStruct(var, (int) componentMap.getSize(), f, isThisParam);
450: 		}
451: 		else {
452: 			// FIXME: How should an existing packed structure be handled? Growing and offset-based placement does not apply
453: 			int len = structDT.isZeroLength() ? 0 : structDT.getLength();
454: 			if (componentMap.getSize() > len) {
455: 				structDT.growStructure((int) componentMap.getSize() - len);
456: 			}
457: 		}
458: 		return structDT;
459: 	}
