461: 	/**
462: 	 * Populate the given structure with any new discovered components in the
463: 	 * offsetToDataTypeMap.
464: 	 * @param structDT is the given structure
465: 	 */
466: 	private void populateStructure(Structure structDT) {
467: 		Iterator<Entry<Long, DataType>> iterator = componentMap.iterator();
468: 		while (iterator.hasNext()) {
469: 			Entry<Long, DataType> entry = iterator.next();
470: 			Long key = entry.getKey();
471: 			DataType valDT = entry.getValue();
472: 			if (key.intValue() < 0) {
473: 				// println("    BAD OFFSET : " + key.intValue());
474: 				continue;
475: 			}
476: 
477: 			// TODO: need to do data type conflict resolution
478: 			if (structDT.getLength() < (key.intValue() + valDT.getLength())) {
479: 				continue;
480: 			}
481: 
482: 			try {
483: 				DataTypeComponent existing = structDT.getComponentAt(key.intValue());
484: 				// try to preserve existing information.
485: 				String name = null;
486: 				String comment = null;
487: 				if (existing != null) {
488: 					name = existing.getFieldName();
489: 					comment = existing.getComment();
490: 				}
491: 				structDT.replaceAtOffset(key.intValue(), valDT, valDT.getLength(), name, comment);
492: 			}
493: 			catch (IllegalArgumentException e) {
494: 				Msg.debug(this, "Unexpected error changing structure offset", e);
495: 			}
496: 		}
497: 	}
