499: 	/**
500: 	 * Create a new structure of a given size. If the associated variable is a 'this' pointer,
501: 	 * make sure there is a the structure is associated with the class namespace.
502: 	 * @param var is the associated variable
503: 	 * @param size is the desired structure size
504: 	 * @param f is the function owning the variable
505: 	 * @param isThisParam is true if the variable is a 'this' variable
506: 	 * @return the new Structure
507: 	 */
508: 	private Structure createNewStruct(HighVariable var, int size, Function f, boolean isThisParam) {
509: 		if (isThisParam) {
510: 			Namespace rootNamespace = currentProgram.getGlobalNamespace();
511: 			Namespace newNamespace = createUniqueClassName(rootNamespace);
512: 			String name = f.getName();
513: 			Symbol symbol = f.getSymbol();
514: 			RenameLabelCmd command =
515: 				new RenameLabelCmd(symbol, name, newNamespace, SourceType.USER_DEFINED);
516: 			if (!command.applyTo(currentProgram)) {
517: 				return null;
518: 			}
519: 			Structure structDT = VariableUtilities.findOrCreateClassStruct(f);
520: 			if (structDT == null) {
521: 				return null;
522: 			}
523: // FIXME: How should an existing packed structure be handled? Growing and offset-based placement does not apply
524: 			int len = structDT.isZeroLength() ? 0 : structDT.getLength();
525: 			if (len < size) {
526: 				structDT.growStructure(size - len);
527: 			}
528: 			return structDT;
529: 		}
530: 		String structName = createUniqueStructName(var, DEFAULT_CATEGORY, DEFAULT_BASENAME);
531: 
532: 		StructureDataType dt = new StructureDataType(new CategoryPath(DEFAULT_CATEGORY), structName,
533: 			size, f.getProgram().getDataTypeManager());
534: 		return dt;
535: 	}
