537: 	private Namespace createUniqueClassName(Namespace rootNamespace) {
538: 		SymbolTable symbolTable = currentProgram.getSymbolTable();
539: 		String newClassBase = "AutoClass";
540: 		String newClassName = "";
541: 		for (int i = 1; i < 1000; ++i) {
542: 			newClassName = newClassBase + Integer.toString(i);
543: 			if (symbolTable.getSymbols(newClassName, rootNamespace).isEmpty()) {
544: 				break;
545: 			}
546: 		}
547: 		// Create the class
548: 		GhidraClass newClass = null;
549: 		try {
550: 			newClass =
551: 				symbolTable.createClass(rootNamespace, newClassName, SourceType.USER_DEFINED);
552: 		}
553: 		catch (DuplicateNameException e) {
554: 			Msg.error(this, "Error creating class '" + newClassName + "'", e);
555: 		}
556: 		catch (InvalidInputException e) {
557: 			Msg.error(this, "Error creating class '" + newClassName + "'", e);
558: 		}
559: 		return newClass;
560: 	}
