566: 	private boolean sanityCheck(long offset, long existingSize) {
567: 
568: 		if (offset < 0) {
569: 			return false; // offsets shouldn't be negative
570: 		}
571: 		if (offset < existingSize) {
572: 			return true; // we have room in the structure
573: 		}
574: 		if (offset > 0x1000) {
575: 			return false; // bigger than existing size; arbitrary cut-off to prevent huge structures
576: 		}
577: 		return true;
578: 	}
