580: 	/**
581: 	 * Get the data-type associated with a Varnode.  If the Varnode is produce by a CAST p-code
582: 	 * op, take the most specific data-type between what it was cast from and cast to.
583: 	 * @param vn is the Varnode to get the data-type for
584: 	 * @return the data-type
585: 	 */
586: 	public static DataType getDataTypeTraceBackward(Varnode vn) {
587: 		DataType res = vn.getHigh().getDataType();
588: 		PcodeOp op = vn.getDef();
589: 		if (op != null && op.getOpcode() == PcodeOp.CAST) {
590: 			Varnode otherVn = op.getInput(0);
591: 			res = MetaDataType.getMostSpecificDataType(res, otherVn.getHigh().getDataType());
592: 		}
593: 		return res;
594: 	}
595: 
596: 	/**
597: 	 * Get the data-type associated with a Varnode.  If the Varnode is input to a CAST p-code
598: 	 * op, take the most specific data-type between what it was cast from and cast to.
599: 	 * @param vn is the Varnode to get the data-type for
600: 	 * @return the data-type
601: 	 */
602: 	public static DataType getDataTypeTraceForward(Varnode vn) {
603: 		DataType res = vn.getHigh().getDataType();
604: 		PcodeOp op = vn.getLoneDescend();
605: 		if (op != null && op.getOpcode() == PcodeOp.CAST) {
606: 			Varnode otherVn = op.getOutput();
607: 			res = MetaDataType.getMostSpecificDataType(res, otherVn.getHigh().getDataType());
608: 		}
609: 		return res;
610: 	}
