612: 	/**
613: 	 * Look for Varnode references that are equal to the given variable plus a
614: 	 * constant offset and store them in the componentMap. The search is performed
615: 	 * by following data-flow paths starting at the given variable. If the variable flows
616: 	 * into a CALL instruction, put it in the addressToCallInputMap if offset is 0.
617: 	 * @param var is the given variable
618: 	 */
619: 	private void fillOutStructureDef(HighVariable var) {
620: 		Varnode startVN = var.getRepresentative();
621: 		ArrayList<PointerRef> todoList = new ArrayList<>();
622: 		HashSet<Varnode> doneList = new HashSet<>();
623: 
624: 		todoList.add(new PointerRef(startVN, 0));	// Base Varnode on the todo list
625: 		Varnode[] instances = var.getInstances();
626: 		for (Varnode vn : instances) {
627: 			doneList.add(vn);		// Mark instances as done to avoid recursion issues
628: 			if (vn != startVN) {
629: 				todoList.add(new PointerRef(vn, 0));	// Make sure all instances are on the todo list
630: 			}
631: 		}
632: 
633: 		// while Todo list not empty
634: 		while (!todoList.isEmpty()) {
635: 			PointerRef currentRef = todoList.remove(0);
636: 			if (currentRef.varnode == null) {
637: 				continue;
638: 			}
639: 
640: 			Iterator<PcodeOp> descendants = currentRef.varnode.getDescendants();
641: 			while (descendants.hasNext()) {
642: 				PcodeOp pcodeOp = descendants.next();
643: 				Varnode output = pcodeOp.getOutput();
644: 				Varnode[] inputs = pcodeOp.getInputs();
645: 				// println("off=" + offset + "     " + pcodeOp.getSeqnum().getTarget().toString() + " : "
646: 				//		+ pcodeOp.toString());
647: 
648: 				DataType outDt;
649: 				long newOff;
650: 				switch (pcodeOp.getOpcode()) {
651: 					case PcodeOp.INT_SUB:
652: 					case PcodeOp.INT_ADD:
653: 						if (!inputs[1].isConstant()) {
654: 							break;
655: 						}
656: 						long value = getSigned(inputs[1]);
657: 						newOff = currentRef.offset +
658: 							((pcodeOp.getOpcode() == PcodeOp.INT_ADD) ? value : (-value));
659: 						if (sanityCheck(newOff, componentMap.getSize())) { // should this offset create a location in the structure?
660: 							putOnList(output, newOff, todoList, doneList);
661: 							// Don't do componentMap.addDataType() as data-type info here is likely uninformed
662: 							componentMap.setMinimumSize(newOff);
663: 						}
664: 						break;
665: 					case PcodeOp.PTRADD:
666: 						if (!inputs[1].isConstant() || !inputs[2].isConstant()) {
667: 							break;
668: 						}
669: 						newOff = currentRef.offset + getSigned(inputs[1]) * inputs[2].getOffset();
670: 						if (sanityCheck(newOff, componentMap.getSize())) { // should this offset create a location in the structure?
671: 							putOnList(output, newOff, todoList, doneList);
672: 							// Don't do componentMap.addReference() as data-type info here is likely uninformed
673: 							componentMap.setMinimumSize(newOff);
674: 						}
675: 						break;
676: 					case PcodeOp.PTRSUB:
677: 						if (!inputs[1].isConstant()) {
678: 							break;
679: 						}
680: 						long subOff = currentRef.offset + getSigned(inputs[1]);
681: 						if (sanityCheck(subOff, componentMap.getSize())) { // should this offset create a location in the structure?
682: 							putOnList(output, subOff, todoList, doneList);
683: 							// Don't do componentMap.addReference() as data-type info here is likely uninformed
684: 							componentMap.setMinimumSize(subOff);
685: 						}
686: 						break;
687: 					case PcodeOp.SEGMENTOP:
688: 						// treat segment op as if it were a cast to complete the value
689: 						//   The segment adds in some unknown base value.
690: 						// get output and add to the Varnode Todo list
691: 						putOnList(output, currentRef.offset, todoList, doneList);
692: 						componentMap.setMinimumSize(currentRef.offset);
693: 						break;
694: 					case PcodeOp.LOAD:
695: 						outDt = getDataTypeTraceForward(output);
696: 						componentMap.addDataType(currentRef.offset, outDt);
697: 
698: 						if (outDt != null) {
699: 							loadPcodeOps.add(new OffsetPcodeOpPair(currentRef.offset, pcodeOp));
700: 						}
701: 
702: 						break;
703: 					case PcodeOp.STORE:
704: 						// create a location in the struct
705: 						//use the type of the varnode being put in to the structure
706: 						if (pcodeOp.getSlot(currentRef.varnode) != 1) {
707: 							break; // store must be into the target structure
708: 						}
709: 						outDt = getDataTypeTraceBackward(inputs[2]);
710: 						componentMap.addDataType(currentRef.offset, outDt);
711: 
712: 						if (outDt != null) {
713: 							storePcodeOps.add(new OffsetPcodeOpPair(currentRef.offset, pcodeOp));
714: 						}
715: 
716: 						break;
717: 					case PcodeOp.CAST:
718: 						putOnList(output, currentRef.offset, todoList, doneList);
719: 						break;
720: 					case PcodeOp.MULTIEQUAL:
721: 						putOnList(output, currentRef.offset, todoList, doneList);
722: 						break;
723: 					case PcodeOp.COPY:
724: 						putOnList(output, currentRef.offset, todoList, doneList);
725: 						break;
726: 					case PcodeOp.CALL:
727: 						if (currentRef.offset == 0) {		// If pointer is passed directly (no offset)
728: 							// find it as an input
729: 							int slot = pcodeOp.getSlot(currentRef.varnode);
730: 							if (slot > 0 && slot < pcodeOp.getNumInputs()) {
731: 								Address storageAddr = computeParamAddress(inputs, slot);
732: 								if (storageAddr != null) {
733: 									addressToCallInputMap.put(inputs[0].getAddress(), storageAddr);
734: 								}
735: 							}
736: 						}
737: 						else {
738: 							outDt = getDataTypeTraceBackward(currentRef.varnode);
739: 							componentMap.addReference(currentRef.offset, outDt);
740: 						}
741: 						break;
742: 					case PcodeOp.CALLIND:
743: 						outDt = getDataTypeTraceBackward(currentRef.varnode);
744: 						componentMap.addReference(currentRef.offset, outDt);
745: 						break;
746: 				}
747: 
748: 			}
749: 		}
750: 	}
751: 
752: 	private long getSigned(Varnode varnode) {
753: 		long mask = 0x80L << ((varnode.getSize() - 1) * 8);
754: 		long value = varnode.getOffset();
755: 		if ((value & mask) != 0) {
756: 			value |= (0xffffffffffffffffL << ((varnode.getSize() - 1) * 8));
757: 		}
758: 		return value;
759: 	}
760: 
761: 	/**
762: 	 * Add a Varnode reference to the current work list to facilitate flow tracing.
763: 	 * To prevent cycles, a separate of visited Varnodes is maintained
764: 	 * @param output is the Varnode at the current point of flow
765: 	 * @param offset is the relative offset of the Varnode to the root variable
766: 	 * @param todoList is the current work list
767: 	 * @param doneList is the visited list
768: 	 */
769: 	private void putOnList(Varnode output, long offset, ArrayList<PointerRef> todoList,
770: 			HashSet<Varnode> doneList) {
771: 		if (doneList.contains(output)) {
772: 			return;
773: 		}
774: 		todoList.add(new PointerRef(output, offset));
775: 		doneList.add(output);
776: 	}
777: 
778: 	/**
779: 	 * Class to create pair between an offset and its related PcodeOp
780: 	 */
781: 	static public class OffsetPcodeOpPair {
782: 
783: 		private Long offset;
784: 		private PcodeOp pcodeOp;
785: 
786: 		public OffsetPcodeOpPair(Long offset, PcodeOp pcodeOp) {
787: 			this.offset = offset;
788: 			this.pcodeOp = pcodeOp;
789: 		}
790: 
791: 		public Long getOffset() {
792: 			return offset;
793: 		}
794: 
795: 		public PcodeOp getPcodeOp() {
796: 			return pcodeOp;
797: 		}
798: 	}
799: }
